<script setup lang="ts">
import {ref,onMounted,onUnmounted,watch,nextTick} from 'vue';
const props=defineProps<{api:(path:string,method?:string,body?:any)=>Promise<any>,can:(permission:string)=>boolean,initialCode?:string}>();
const emit=defineEmits<{reader:[id:number]}>();
const code=ref(props.initialCode||''),branch=ref<number|null>(Number(localStorage.getItem('reader-visit-branch'))||null),notes=ref(''),branches=ref<any[]>([]),found=ref<any>(null),result=ref<any>(null),journal=ref<any>({items:[],total:0}),stats=ref<any>(null),offset=ref(0),busy=ref(false),error=ref(''),input=ref<HTMLInputElement|null>(null);let generation=0,timer:ReturnType<typeof setTimeout>;
function dateTime(v:string){return new Date(v.endsWith('Z')||/[+-]\d\d:\d\d$/.test(v)?v:v+'Z').toLocaleString('ru-RU',{timeZone:'Asia/Almaty'});}
watch(branch,v=>localStorage.setItem('reader-visit-branch',String(v||'')));
watch(code,()=>{const token=++generation;found.value=null;error.value='';clearTimeout(timer);if(!code.value.trim())return;timer=setTimeout(async()=>{try{const r=await props.api('/visits/lookup?code='+encodeURIComponent(code.value));if(token===generation)found.value=r;}catch(e){if(token===generation)error.value=String(e);}},250);},{immediate:true});
async function refresh(){if(props.can('visits.view')){[journal.value,stats.value]=await Promise.all([props.api('/visits?offset='+offset.value),props.api('/visits/analytics')]);}}
async function scan(){if(busy.value)return;busy.value=true;error.value='';clearTimeout(timer);generation++;try{result.value=await props.api('/visits','POST',{code:code.value,branch_id:branch.value,notes:notes.value,source:'desk'});code.value='';notes.value='';found.value=null;await refresh();}catch(e){error.value=String(e);}finally{busy.value=false;await nextTick();input.value?.focus();}}
onUnmounted(()=>{generation++;clearTimeout(timer);});
onMounted(async()=>{try{branches.value=(await props.api('/reader-branches')).filter((b:any)=>b.active);if(!branches.value.some(b=>b.id===branch.value))branch.value=branches.value[0]?.id||null;await refresh();input.value?.focus();}catch(e){error.value=String(e);}});
</script>
<template><section class="visits-page"><div class="page-heading"><div><h1>Посещения</h1><p>Регистрация физического прихода по читательскому билету · время Алматы</p></div></div><p v-if="error" class="error" role="alert">{{error}}</p>
<form v-if="can('visits.record')" class="card" @submit.prevent="scan"><label>Пункт обслуживания<select v-model="branch" required><option :value="null">Выберите пункт</option><option v-for="b in branches" :value="b.id">{{b.name}}</option></select></label><label class="scan-label">Штрихкод или номер читательского билета<input ref="input" v-model="code" maxlength="100" class="scan-input" autocomplete="off" placeholder="Отсканируйте билет и нажмите Enter" required :disabled="busy"></label><p v-if="found">{{found.full_name}} · {{found.ticket_number}} · {{({active:'Активен',blocked:'Заблокирован',suspended:'Приостановлен'} as any)[found.status]||found.status}} {{found.block_reason}}</p><label>Примечание<input v-model="notes" maxlength="1000"></label><button class="primary" :disabled="busy||!branch">{{busy?'Регистрация…':'Зарегистрировать посещение'}}</button><p v-if="!branches.length">Сначала добавьте пункт обслуживания в разделе «Читатели».</p></form>
<div v-if="result" class="card" role="status"><strong>{{result.duplicate?'Повторный скан: посещение уже учтено':'Посещение зарегистрировано'}}</strong><p>{{result.full_name}} · {{dateTime(result.scanned_at)}}</p></div>
<div v-if="stats" class="card"><h2>Физические посещения</h2><div class="visit-metrics"><p><strong>{{stats.today.visits}}</strong> сегодня</p><p><strong>{{stats.today.unique}}</strong> уникальных читателей сегодня</p><p><strong>{{stats.visits}}</strong> за 7 дней</p></div><div class="visit-days"><div v-for="d in stats.days"><span>{{d.date}}</span><strong>{{d.visits}}</strong></div></div><p v-for="b in stats.branches">{{b.name}}: {{b.visits}}</p></div>
<div v-if="can('visits.view')" class="card table-wrap"><h2>Журнал посещений</h2><table><thead><tr><th>Дата и время</th><th>Читатель / билет</th><th>Пункт</th><th>Сотрудник</th><th>Источник / примечание</th></tr></thead><tbody><tr v-for="v in journal.items"><td>{{dateTime(v.scanned_at)}}</td><td><button v-if="can('readers.registry.view')" @click="emit('reader',v.reader_id)">{{v.full_name}}</button><span v-else>{{v.full_name}}</span><small>{{v.ticket_number}}</small></td><td>{{v.branch}}</td><td>{{v.actor}}</td><td>{{({desk:'Рабочее место',kiosk:'Киоск',turnstile:'Турникет'} as any)[v.source]||v.source}} {{v.notes}}</td></tr><tr v-if="!journal.items.length"><td colspan="5">Посещений пока нет</td></tr></tbody></table><button :disabled="offset===0" @click="offset-=50;refresh()">Назад</button><span> {{journal.total?offset+1:0}}–{{Math.min(offset+50,journal.total)}} из {{journal.total}} </span><button :disabled="offset+50>=journal.total" @click="offset+=50;refresh()">Далее</button></div></section></template>
<style scoped>.visits-page .card{padding:24px;margin:20px 0}.visits-page .scan-input{box-sizing:border-box}.visits-page form button{margin-top:10px}.scan-label{display:block;margin:24px 0}.scan-input{display:block;width:100%;font-size:26px;padding:18px;margin-top:10px}.visits-page label{display:block;margin-bottom:16px}.visits-page small{display:block}.visit-metrics,.visit-days{display:flex;gap:24px;flex-wrap:wrap}.visit-metrics strong{display:block;font-size:32px}.visit-days div{display:grid;gap:12px;text-align:center;padding:12px;background:#f1f5f9}.visit-days strong{font-size:24px}</style>
